DECLARE p jsonb := $payload${"ley":{"id":"29886758-c194-5db4-86eb-8c96347f7aba","titulo":"Acuerdo por el que se emite la segunda modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante [DOF 10/07/2026]","siglas":"CONV-ESTRATEGICOS-M2","fecha_publicacion":"2026-07-10","fecha_ultima_reforma":null,"vigente":null,"temas_clave":["Proyectos estratégicos de generación y almacenamiento","Convocatorias","Modificación","Interconexión"],"url_original":"https://sidof.segob.gob.mx/notas/docFuente/5793261","tipo":"acuerdo"},"articulos":[{"id":"22635122-f6db-5ea6-9241-e0e09c228814","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":0,"identificador":"Nota editorial · versiones relacionadas","contenido":"### Nota editorial · versión publicada y documentos relacionados\n\nEste registro reproduce la publicación del DOF de 10/07/2026. Se conserva el texto de esa publicación; las modificaciones se consultan en registros separados. No es un texto consolidado ni una indicación de que todos sus plazos permanezcan abiertos.\n\nDocumentos de la misma convocatoria incorporados al acervo:\n\n- <a href=\"/#ley-24110e92-4d4c-5434-b02a-6a1794ee65ff\" target=\"_blank\" rel=\"noopener noreferrer\">Texto original · 15/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5787666)\n- <a href=\"/#ley-373ce6df-4e78-59d9-aae5-54007a446c59\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 1 · 26/05/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5788508)\n- <a href=\"/#ley-29886758-c194-5db4-86eb-8c96347f7aba\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 2 · 10/07/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5793261)\n- <a href=\"/#ley-372339cc-7ed9-5e5c-8023-647e1a12c3b6\" target=\"_blank\" rel=\"noopener noreferrer\">Modificación 3 · 02/09/2026</a> · [fuente oficial](https://sidof.segob.gob.mx/notas/docFuente/5797703)\n\nEsta nota es información editorial del buscador y no forma parte de la publicación oficial. Referencias del radar con corte al 14 de septiembre de 2026, cotejadas para esta incorporación.\n","tipo_articulo":"complementario","titulo_nombre":"Información editorial de la versión","capitulo_nombre":null,"seccion_nombre":null},{"id":"4e69208e-0750-5a71-823a-65353b442ee6","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":1,"identificador":"Preámbulo del acuerdo modificatorio","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n ACUERDO por el que se emite la segunda modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante.\n Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Secretaría de Energía.\n<div> LUZ ELENA GONZÁLEZ ESCOBAR, Secretaria de Energía, con fundamento en lo dispuesto por los artículos 28, párrafo noveno, 90, párrafo primero de la Constitución Política de los Estados Unidos Mexicanos; 2, fracción I, 14, párrafo primero, 26, fracción IX y 33, fracciones I, IV, V, XXIX y XXXIII de la Ley Orgánica de la Administración Pública Federal; 4 de la Ley Federal de Procedimiento Administrativo; 2, 10, fracciones I, VI y XIV, 16, 36 y 38 de la Ley del Sector Eléctrico; 2, fracción XXV, 3, 13 y 28 del Reglamento de la Ley del Sector Eléctrico y 2, fracción III de la Ley de Planeación y Transición Energética, y</div>\n<div> CONSIDERANDO<br> </div>\n<div> Que el 15 de mayo de 2026 se publicó en el Diario Oficial de la Federación la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante, dirigida a las personas interesadas en desarrollar proyectos estratégicos de generación y almacenamiento de energía eléctrica alineados a la planeación vinculante del sector eléctrico, misma que fue modificada mediante Acuerdo publicado en el Diario Oficial de la Federación el 26 de mayo de 2026.</div>\n<div> Que la citada Convocatoria establece el mecanismo para la atención prioritaria de las solicitudes para la obtención de permisos, los estudios de interconexión y conexión y, en su caso, la celebración de los contratos de interconexión y conexión, que permita el desarrollo de proyectos estratégicos de generación de energía eléctrica renovable y Sistemas de Almacenamiento de Energía Eléctrica que se desarrollen bajo Proyecto en Asociación con la Comisión Federal de Electricidad que se requieran para fortalecer la Confiabilidad, Continuidad, Eficiencia, Seguridad y Sostenibilidad del Sistema Eléctrico Nacional.</div>\n<div> Que derivado del interés manifestado por las personas participantes, con la finalidad de incentivar la participación y precisar las etapas para fortalecer la revisión realizada por las diversas autoridades y entes participantes y dar mayor claridad en la mencionada Convocatoria, evitando costos innecesarios a los particulares y favoreciendo la eficiencia administrativa, resulta procedente modificar la referida Convocatoria, sin que esta modificación incorpore requisitos adicionales de elegibilidad o modifique el tipo de proyectos que son susceptibles de participar en la misma, por lo que he tenido a bien emitir el siguiente:</div>\n<div> ACUERDO POR EL QUE SE EMITE LA SEGUNDA MODIFICACIÓN A LA CONVOCATORIA PARA LA ATENCIÓN DE<br> PROYECTOS ESTRATÉGICOS DE GENERACIÓN Y ALMACENAMIENTO DE ENERGÍA ELÉCTRICA, ALINEADOS A<br> LA PLANEACIÓN VINCULANTE<br> </div>","tipo_articulo":"preambulo","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":null,"seccion_nombre":null},{"id":"f0eb0333-b24e-59f0-9056-acdfbdcdf6eb","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":2,"identificador":"PRIMERO · Alcance de las modificaciones","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> PRIMERO. Se modifican los numerales 1, fracciones IV y V; 2, fracción V; 3.1, fracciones XI y XII; 5.1; 8.1, segundo párrafo; 8.3, fracción II y séptimo párrafo; 9.1., fracción II, 10.1, primer párrafo y fracciones I y II; 10.2; 10.3; 11.1, primer párrafo; 12.1; 14; 17.1; 17.2; 17.3, primer párrafo; 17.4; 18, primer y segundo párrafo; 18.1, segundo párrafo y el encabezado de la segunda columna de la tabla del numeral 18.2, segundo párrafo; se adicionan una fracción XIV recorriendo la subsecuente del numeral 3.1; un segundo párrafo al numeral 6.2 y un segundo y tercer párrafos al numeral 17.3; se precisa el numeral 17.4.1, y se eliminan las fracciones VI y VII del numeral 2, renumerándose las siguientes, todos de la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante, para quedar en los siguientes términos:</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":null},{"id":"debba957-23f7-5437-8426-c7ad6b65a0ef","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":3,"identificador":"PRIMERO · Texto citado del numeral 1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;1...</div>\n<div> 1.1...</div>\n<div> I. a III ...</div>\n<div> IV. Establecer la Capacidad Requerida para la Convocatoria de Proyectos Estratégicos para los proyectos que se presenten conforme a los términos de la Convocatoria de Proyectos Estratégicos, considerando las necesidades energéticas del Sistema Eléctrico Nacional de acuerdo con la planeación vinculante;</div>\n<div> V. Establecer el procedimiento para que las personas solicitantes registren sus solicitudes bajo Proyectos en Asociación con la CFE, y</div>\n<div> VI. ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 1"},{"id":"e1f3d3d3-2a5d-546b-a736-42676d6b6c29","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":4,"identificador":"PRIMERO · Texto citado del numeral 2","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;2. ...</div>\n<div> I. a IV. ...</div>\n<div> V. Capacidad Requerida para la Convocatoria de Proyectos Estratégicos: Para los efectos de la presente Convocatoria de Proyectos Estratégicos, la capacidad requerida, expresada en MW, comprende la capacidad de generación de energía eléctrica por sistema interconectado, así como la potencia de los SAEE por Gerencia de Control Regional. Dicha capacidad constituye el objetivo a cubrir mediante los proyectos que participen en la Convocatoria, a fin de atender las necesidades prioritarias del Sistema Eléctrico Nacional, y se cubrirá de manera progresiva conforme a lo previsto en la presente Convocatoria;</div>\n<div> VI. Convocatoria de Proyectos Estratégicos: La Convocatoria para la atención de Proyectos Estratégicos de generación y almacenamiento de energía eléctrica, alineados a la planeación vinculante;</div>\n<div> VII. Disposiciones de la Planeación Vinculante: Disposiciones administrativas de carácter general para la planeación vinculante aplicables a la generación de energía eléctrica publicadas en el Diario Oficial de la Federación el 17 de octubre de 2025 y, las Disposiciones administrativas de carácter general para la planeación vinculante aplicables a Almacenamiento de Energía Eléctrica que para tal efecto emita la SENER;</div>\n<div> VIII. Disposiciones de Permisos: Disposiciones administrativas de carácter general que establecen los términos legales, técnicos y financieros para solicitar el otorgamiento y la modificación de permisos de generación y de almacenamiento de energía eléctrica, así como su vigencia, publicadas en el Diario Oficial de la Federación el 23 de octubre de 2025;</div>\n<div> IX. Disposiciones de Integración de SAEE: Disposiciones Administrativas de Carácter General para la integración de Sistemas de Almacenamiento de Energía Eléctrica al Sistema Eléctrico Nacional publicadas en el Diario Oficial de la Federación el 16 de abril de 2026;</div>\n<div> X. Entrada en Operación Comercial: Fecha determinada en la planeación vinculante en la que un proyecto debe iniciar operaciones comerciales y que constituye el parámetro temporal obligatorio para validar criterios de firmeza para el desarrollo de los proyectos presentados en las solicitudes correspondientes;</div>\n<div> XI. Esquema de Desarrollo Mixto: Modalidad de participación para el desarrollo de proyectos entre la CFE y particulares para el desarrollo de proyectos de generación conforme a la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, los lineamientos aplicables y los instrumentos que se suscriban para cada proyecto;</div>\n<div> XII. Grupo de Análisis Técnico o GAT: Grupo integrado en términos de las Disposiciones de la Planeación Vinculante;</div>\n<div> XIII. LCNE: Ley de la Comisión Nacional de Energía;</div>\n<div> XIV. LPTE: Ley de Planeación y Transición Energética;</div>\n<div> XV. LSE: Ley del Sector Eléctrico;</div>\n<div> XVI. MW: Megawatt;</div>\n<div> XVII. MIC: Manual de Interconexión de Centrales Eléctricas y Conexión de Centros de Carga publicado en el Diario Oficial de la Federación el 9 de febrero de 2018 o aquel que lo sustituya;</div>\n<div> XVIII. Nivel de Tensión: Magnitud de voltaje en el que la Central Eléctrica o el Sistema de Almacenamiento de Energía Eléctrica se conecta o interconecta, según corresponda, al SEN, expresado en kilovoltios;</div>\n<div> XIX. OPE: Oficialía de Partes Electrónica, herramienta tecnológica con la que cuenta la CNE, para recibir y dar seguimiento a las solicitudes de permisos presentadas en términos de la Convocatoria de Proyectos Estratégicos, así como para dar seguimiento a los permisos de generación y almacenamiento de energía eléctrica. Dicha herramienta se regula con base en lo establecido en las reglas generales para su funcionamiento publicadas en el Diario Oficial de la Federación, y se encuentra disponible en el portal https://ope.cne.gob.mx/;</div>\n<div> XX. Potencia SAEE: Potencia activa, expresada en MW (a seis dígitos después del punto decimal), e indicada en corriente alterna, mediante la cual se designa e identifica al Sistema de Almacenamiento de Energía Eléctrica;</div>\n<div> XXI. Punto de Interconexión: Punto físico de la Red Nacional de Transmisión o de las Redes Generales de Distribución donde una Central Eléctrica se interconecta físicamente al SEN para inyectar energía eléctrica o donde un Sistema de Almacenamiento de Energía Eléctrica se conecta al SEN para cargar energía eléctrica;</div>\n<div> XXII. Proyecto en Asociación con la CFE: Proyecto cuya ejecución se plantea con participación de la Comisión Federal de Electricidad, mediante un Esquema para el Desarrollo Mixto, sea Inversión Mixta, Producción de Largo Plazo, asociación, alianza o cualquier otra modalidad permitida por la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad, los Lineamientos de los Esquemas para el Desarrollo Mixto de la CFE y demás disposiciones aplicables;</div>\n<div> XXIII. RLPTE: Reglamento de la Ley de Planeación y Transición Energética;</div>\n<div> XXIV. RLSE: Reglamento de la Ley del Sector Eléctrico;</div>\n<div> XXV. SENER: Secretaría de Energía;</div>\n<div> XXVI. SEN: Sistema Eléctrico Nacional;</div>\n<div> XXVII. SIASIC: Sistema de Atención a Solicitudes de Interconexión y Conexión del CENACE;</div>\n<div> XXVIII. Subestación: Instalación de la RNT o de las RGD en donde un elemento de generación de energía eléctrica o Sistema de Almacenamiento de Energía Eléctrica se conecta o interconecta físicamente, según su condición operativa, al SEN; para cargar o inyectar energía eléctrica, y</div>\n<div> XXIX. VUPE: Ventanilla Única de Proyectos Estratégicos del Sector Energético disponible en el portal https://ventanillaunica.energia.gob.mx, habilitada como un módulo para el seguimiento de proyectos del sector.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 2"},{"id":"ef7fd98c-0659-55e8-9062-2b6d2dec1d85","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":5,"identificador":"PRIMERO · Texto citado del numeral 3.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;3.1. ...</div>\n<div> I. a la X. ...</div>\n<div> XI. El CENACE no debe considerar proyectos que correspondan a regiones donde no exista Capacidad Requerida para la Convocatoria de Proyectos Estratégicos o que esta haya sido cubierta;</div>\n<div> XII. Los proyectos asociados a solicitudes ingresadas al amparo de la presente Convocatoria pueden participar simultáneamente en otras convocatorias;</div>\n<div> XIII. y XIV. ...</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 3.1"},{"id":"0d2b15e2-8d88-5dd8-961c-0ad918173854","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":6,"identificador":"PRIMERO · Texto citado del numeral 5.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;5.1. La SENER, la CNE, el CENACE y la CFE, en el ámbito de sus atribuciones, deben realizar las gestiones necesarias para atender las solicitudes, estudios y procedimientos conforme a los plazos de la presente Convocatoria de Proyectos Estratégicos.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 5.1"},{"id":"da2deaa4-bf51-5f2f-a31b-58d13cff0f4c","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":7,"identificador":"PRIMERO · Texto citado del numeral 6.2","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;6.2. ...</div>\n<div> Las etapas y plazos previstos en esta Convocatoria son secuenciales y su desarrollo se encuentra sujeto al cumplimiento de cada etapa inmediata anterior correspondiente, por lo que en caso de no cumplirse alguna de ellas, la persona solicitante no puede continuar con las etapas subsecuentes del procedimiento, salvo aquellas etapas que determinen una excepción. Lo anterior, sin perjuicio de los supuestos específicos de conclusión o desechamiento expresamente previstos en esta Convocatoria.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 6.2"},{"id":"c8185c2f-1362-5fd8-b0ad-02821ea03a0a","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":8,"identificador":"PRIMERO · Texto citado del numeral 8.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;8.1 ...</div>\n<div> Presentado el formato al que hace referencia el párrafo anterior y celebrado el contrato o instrumento jurídico que formalice el Proyecto en Asociación con la CFE en términos de la normatividad aplicable, la persona solicitante o la CFE pueden presentar la solicitud de permiso correspondiente para que la CNE realice su evaluación de conformidad con los requisitos establecidos en la LSE, el RLSE, la LPTE, el RLPTE, la Convocatoria de Proyectos Estratégicos y demás disposiciones aplicables.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 8.1"},{"id":"ae48e102-9adb-54b8-8d6a-7256b6d77a49","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":9,"identificador":"PRIMERO · Texto citado del numeral 8.3","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;8.3. ...</div>\n<div> I. ...</div>\n<div> II. Costo estimado, en pesos mexicanos, de las Obras de Refuerzo. Cuando estas sean comunes a dos o más proyectos, los costos se asignan de manera proporcional a la potencia en MW de cada proyecto de generación o almacenamiento de energía eléctrica, considerando que se cubra el requerimiento de Capacidad Requerida para la Convocatoria de Proyectos Estratégicos, siempre que la o las personas solicitantes acepten los términos y continúen con lo previsto en la Convocatoria de Proyectos Estratégicos, y</div>\n<div> III. ...</div>\n<div> ...</div>\n<div> ...</div>\n<div> En caso de no recibirse esta aceptación a través de la VUPE, en los términos previstos, el CENACE debe emitir el oficio correspondiente en el que se notifique lo conducente.</div>\n<div> ...</div>\n<div> ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 8.3"},{"id":"d84cec6a-0dc5-57b8-9df2-31cbceb48dec","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":10,"identificador":"PRIMERO · Texto citado del numeral 9.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;9.1. ...</div>\n<div> I. ...</div>\n<div> II. Al CENACE, los estudios técnicos referidos en la Convocatoria de Proyectos Estratégicos, incluyendo la información necesaria para verificar el cumplimiento de los criterios de planeación vinculante, según le corresponda, establecidos en las Disposiciones de la Planeación Vinculante y dar continuidad a las etapas subsecuentes del procedimiento.</div>\n<div> ...</div>\n<div> ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 9.1"},{"id":"742f38a6-3cd3-5894-8953-ec74c4a003ee","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":11,"identificador":"PRIMERO · Texto citado del numeral 10.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;10.1. La SENER debe someter a consideración del Grupo de Análisis Técnico la evaluación de los proyectos que cumplan con los requisitos establecidos en la LSE, el RLSE, la LPTE, el RLPTE, la Convocatoria de Proyectos Estratégicos y demás disposiciones aplicables, para lo cual debe remitir los expedientes administrativos correspondientes.</div>\n<div> ...</div>\n<div> I. Emitir la opinión técnica a que se refiere la etapa 10 del numeral 17.1, respecto de la evaluación realizada por la SENER y el CENACE de los proyectos presentados al amparo de la Convocatoria de Proyectos Estratégicos, y</div>\n<div> II. Identificar aquellos proyectos que proporcionen los mayores beneficios para el SEN y el Estado, en el caso de que los proyectos que resulten elegibles para obtener un permiso al amparo de la Convocatoria de Proyectos Estratégicos. Para el cumplimiento de lo anterior, deben considerar al menos lo siguiente respecto de los proyectos evaluados: Entrada en Operación Comercial, ubicación; elementos técnicos básicos del proyecto; alivio de congestión; aportación de potencia; mejora de la confiabilidad regional y del SEN, flexibilidad operativa; aportaciones socioambientales; tecnología y desempeño proyectado del Sistema de Almacenamiento de Energía Eléctrica; forma de ejecución y financiamiento, y eficiencia económica.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 10.1"},{"id":"2d5af28d-8023-5f97-b921-8e5555f40d9f","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":12,"identificador":"PRIMERO · Texto citado del numeral 10.2","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;10.2. La SENER debe notificar la opinión del GAT a la CFE, a la CNE y a las personas solicitantes a través de la VUPE, para que, en su caso, se continúe con lo previsto en el numeral 17.3 de esta Convocatoria.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 10.2"},{"id":"e7e8fc0f-f2ba-593e-8d9a-167a887ec6be","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":13,"identificador":"PRIMERO · Texto citado del numeral 10.3","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;10.3. Una vez emitida la opinión del GAT, en caso de no continuar con el procedimiento, las personas solicitantes pueden presentar por las vías ordinarias las solicitudes para la obtención de los diversos permisos, autorizaciones y demás actos administrativos correspondientes, en los términos previstos en la normatividad aplicable.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 10.3"},{"id":"54befe15-f49b-56d0-8e63-6da0c945c935","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":14,"identificador":"PRIMERO · Texto citado del numeral 11.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;11.1. Una vez emitida la opinión técnica por parte del Grupo de Análisis Técnico, la SENER debe proporcionar a la CFE el expediente del proyecto, a través de la VUPE, para que, en su caso, se continúe el procedimiento conforme a lo previsto en el numeral 17.3 de la presente Convocatoria.</div>\n<div> ...&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 11.1"},{"id":"179a0db8-7070-51aa-be39-d9d17cdd0b13","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":15,"identificador":"PRIMERO · Texto citado del numeral 12.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;12.1. La CNE debe resolver sobre la solicitud de permiso presentada por la persona solicitante, considerando los plazos establecidos en el numeral 17.4 de la presente convocatoria y de conformidad con lo previsto en la LSE, el RLSE y la demás normatividad aplicable, para lo cual le debe ser remitido el expediente administrativo que incluya toda la información presentada por la persona solicitante, así como la proporcionada por la SENER, el CENACE y la CFE.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 12.1"},{"id":"534c31ee-29fa-53db-9882-66677a41ca24","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":16,"identificador":"PRIMERO · Texto citado del numeral 14","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;14. Publicación periódica de capacidades y resultados de la Convocatoria de Proyectos Estratégicos</div>\n<div> La SENER puede publicar y, en su caso, actualizar la Capacidad Requerida para la Convocatoria de Proyectos Estratégicos, así como el listado de proyectos que cumplieron con los requisitos correspondientes y con los criterios de planeación vinculante, y que obtuvieron un permiso con base en esta Convocatoria, en la página https://ventanilla.energia.gob.mx/.</div>\n<div> Las publicaciones a las que hace referencia este numeral tienen carácter informativo y no sustituyen los actos, estudios, resoluciones o notificaciones que correspondan conforme a la normatividad aplicable.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 14"},{"id":"fbed5ce0-0c02-5a9a-a4d6-11506d12a5b9","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":17,"identificador":"PRIMERO · Texto citado del numeral 17.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;17.1 Para el desarrollo de la Convocatoria de Proyectos Estratégicos, el procedimiento de registro de manifestación de interés y solicitud de estudios de conexión e interconexión queda sujeto a las etapas, plazos y actividades siguientes:</div>\n<div> En todos los casos, el procedimiento queda sujeto a lo siguiente:</div>\n<table> <tbody><tr> <td> <div> No. de<br> Etapa<br> </div> </td> <td> <div> Alcance<br> </div> </td> <td> <div> Fechas/plazos (días<br> hábiles)<br> </div> </td> <td colspan=\"2\"> <div> Descripción de la actividad<br> </div> </td> </tr> <tr> <td> <div> 1<br> </div> </td> <td> <div> Publicación de la Convocatoria de Proyectos Estratégicos.</div> </td> <td> <div> 15 de mayo<br> </div> </td> <td colspan=\"2\"> <div> SENER publica en el DOF la Convocatoria de Proyectos Estratégicos.</div> </td> </tr> <tr> <td> <div> 2<br> </div> </td> <td> <div> Registro de manifestación de interés y solicitud de estudios de interconexión y conexión.</div> </td> <td> <div> 2 de junio al 2 de<br> septiembre de 2026<br> </div> </td> <td colspan=\"2\"> <div> La persona solicitante debe registrar su manifestación de interés y la solicitud de estudios de conexión e interconexión, según corresponda, a través de la VUPE en el formato previsto para tales efectos.</div> </td> </tr> <tr> <td> <div> 3<br> </div> </td> <td> <div> Prevención y atención de prevención de registro y solicitud.</div> </td> <td> <div> 7 días<br> </div> </td> <td colspan=\"2\"> <div> Una vez recibida la solicitud de estudios de conexión e interconexión, según corresponda, en los casos en que la solicitud no contenga los datos e información correspondientes o no cumpla con los requisitos establecidos, el CENACE debe desahogar la etapa de prevención dentro de un plazo de siete días hábiles. Para tal efecto, debe prevenir a la persona solicitante dentro de los primeros dos días hábiles de esta etapa, para que subsane lo conducente dentro de los 5 días hábiles siguientes.</div> <div> Vencido el plazo previsto en el párrafo anterior, en caso de que no se atienda la prevención en tiempo y forma, el CENACE debe desechar la solicitud correspondiente y notificar dicha determinación a la persona solicitante.</div> </td> </tr> <tr> <td> <div> 4<br> </div> </td> <td> <div> CFE manifiesta si es de su interés que se evalúe el proyecto presentado para asociarse en términos de sus directrices y de la Convocatoria de Proyectos Estratégicos.</div> </td> <td> <div> 10 días<br> </div> </td> <td colspan=\"2\"> <div> La CFE debe revisar los registros de manifestación de interés de los proyectos presentados en la Convocatoria de Proyectos Estratégicos, para manifestar si es de su interés que se evalúe el proyecto presentado para asociarse en términos de sus directrices y de la Convocatoria de Proyectos Estratégicos, e informarse a través de la VUPE, para continuar con el procedimiento previsto en esta Convocatoria.</div> <div> En el caso de que la CFE manifieste que no es de su interés que se evalúe el proyecto, se da por concluido el procedimiento previsto en esta Convocatoria.</div> </td> </tr> <tr> <td> <div> 5<br> </div> </td> <td> <div> Determinación de pagos por estudios de conexión e interconexión.</div> </td> <td> <div> 2 días<br> </div> </td> <td colspan=\"2\"> <div> Determinados los pagos por los estudios correspondientes, por medio de la VUPE, el CENACE debe comunicar a las personas solicitantes alguna de las siguientes opciones:</div> <div> 1.   El monto a pagar, para lo cual se le notifica a la persona solicitante la línea de captura de pago correspondiente, o</div> <div> 2.   Que la información presentada resulta suficiente para la revalidación de los estudios correspondientes, por lo que no debe realizar un pago adicional. En este supuesto, no aplican las etapas 6 y 7 subsecuentes.</div> </td> </tr> <tr> <td> <div> 6<br> </div> </td> <td> <div> Pago de estudios de conexión e interconexión.</div> </td> <td> <div> 5 días<br> </div> </td> <td colspan=\"2\"> <div> Cuando así proceda, la persona solicitante debe presentar, por medio de la VUPE, el comprobante del pago de los estudios de conexión e interconexión que, en su caso, haya informado el CENACE.</div> </td> </tr> <tr> <td> <div> 7<br> </div> </td> <td> <div> Realización de estudios de interconexión y conexión.</div> </td> <td> <div> 30 días<br> </div> </td> <td colspan=\"2\"> <div> Una vez validado el pago por los estudios, el CENACE debe realizar los estudios correspondientes conforme a lo previsto en el MIC. La persona solicitante debe revisar las notificaciones que se realicen a través de la VUPE.</div> </td> </tr> <tr> <td> <div> 8<br> </div> </td> <td> <div> Notificación de resultados de estudios y costos de Obras de Refuerzo y costos de interconexión.</div> </td> <td> <div> 1 día<br> </div> </td> <td colspan=\"2\"> <div> El CENACE debe notificar a la persona solicitante y a la CNE el resultado de los estudios de conexión e interconexión o su revalidación, según corresponda, a más tardar el día hábil siguiente transcurrido el plazo para la elaboración de los estudios. </div> </td> </tr> <tr> <td> <div> 9<br> </div> </td> <td> <div> Aceptación de costos de Obras de Refuerzo y de Interconexión.</div> </td> <td> <div> 5 días<br> </div> </td> <td colspan=\"2\"> <div> Una vez notificado el resultado de los estudios o su revalidación, la persona solicitante, en su caso, debe presentar a través de la VUPE, el Anexo 19.3, Formato Aceptación de Obras.</div> <div> En el caso de que la persona solicitante no acepte los costos de las Obras de Refuerzo y de Interconexión, el CENACE debe concluir la solicitud de interconexión y conexión y, por lo tanto, el procedimiento previsto en esta Convocatoria.</div> </td> </tr> <tr> <td> <div> 10<br> </div> </td> <td> <div> Revisión de información técnica y emisión de Opinión del Grupo de Análisis Técnico.</div> </td> <td> <div> 5 días<br> </div> </td> <td colspan=\"2\"> <div> El Grupo de Análisis Técnico debe revisar la información técnica que, en su caso, le remita la SENER, el CENACE o la CFE, respecto de los proyectos que presenten su registro de manifestación de interés en términos de la Convocatoria de Proyectos Estratégicos y emitir su opinión técnica.</div> </td> </tr> </tbody></table>\n<div> &quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 17.1"},{"id":"2ee2f47a-0cfe-5f3e-84f1-154d89efb548","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":18,"identificador":"PRIMERO · Texto citado del numeral 17.2","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;17.2. La SENER debe notificar, a través de la VUPE, la opinión emitida por el Grupo de Análisis Técnico a la que se refiere la etapa 10 prevista en el numeral 17.1 de la Convocatoria de Proyectos Estratégicos, a la persona solicitante, a la CFE y a la CNE.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 17.2"},{"id":"41d2628f-bcb0-54f1-9af8-d5ff6acecf13","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":19,"identificador":"PRIMERO · Texto citado del numeral 17.3","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;17.3. Emitida la opinión del Grupo de Análisis Técnico a la que se refiere la etapa 10 prevista en el numeral 17.1, la CFE debe iniciar el procedimiento correspondiente para que, en su caso, formalice el Proyecto en Asociación con la CFE.</div>\n<div> Para la formalización de los contratos o instrumentos jurídicos del Proyecto Estratégico con la CFE, se debe estar a lo previsto en la LSE, el RLSE, la LPTE, el RLPTE, la Ley de la Empresa Pública del Estado, Comisión Federal de Electricidad y su reglamento y, en su caso, a los Lineamientos de los Esquemas para el Desarrollo Mixto de la Empresa Pública del Estado, Comisión Federal de Electricidad y demás normatividad aplicable.</div>\n<div> En caso de que no se formalice el Proyecto en Asociación con la CFE, la empresa pública del Estado lo debe informar a la SENER a efecto de que esta notifique, a través de la VUPE, la conclusión del procedimiento. Lo anterior, sin perjuicio de que la persona interesada pueda participar en otras convocatorias, conforme a la normatividad aplicable.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 17.3"},{"id":"93f0f7e8-d5c9-5e10-a144-e09219222c50","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":20,"identificador":"PRIMERO · Texto citado del numeral 17.4","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;17.4 Formalizado el Proyecto en Asociación con la CFE, la persona solicitante o la CFE, debe presentar la solicitud del permiso que corresponda de conformidad con las etapas, plazos y actividades siguientes:</div>\n<table> <tbody><tr> <td> <div> No. de<br> Etapa<br> </div> </td> <td> <div> Alcance<br> </div> </td> <td> <div> Plazos (días hábiles)<br> </div> </td> <td> <div> Descripción de actividad<br> </div> </td> </tr> <tr> <td> <div> 1<br> </div> </td> <td> <div> Presentación de la solicitud de permiso.</div> </td> <td> <div> 15 días<br> </div> </td> <td> <div> La persona solicitante o la CFE debe ingresar, a través de la OPE, la solicitud de permiso correspondiente, de conformidad con lo establecido en las Disposiciones de Permisos.</div> <div> En su caso, la persona solicitante puede optar por alguna de las siguientes opciones, según corresponda:</div> <div> 1.   Sin trámite previo. Cuando la persona solicitante no cuente con ninguna solicitud de permiso en trámite ante la CNE, debe presentar el formato de solicitud de permiso correspondiente a través de la OPE, o</div> <div> 2.   Con trámite previo. Cuando la persona solicitante ya cuente con una solicitud de permiso previo a la presentación del registro de manifestación de interés en términos de la Convocatoria de Proyectos Estratégicos, debe presentar a través de la OPE, el Formato Solicitudes de Permiso con Trámite Previo.</div> <div> Durante esta etapa la SENER y el CENACE deben remitir a la CNE la información a la que se refiere el numeral 9.1 de esta Convocatoria. </div> </td> </tr> <tr> <td> <div> 2<br> </div> </td> <td> <div> Revisión de requisitos y prevención.</div> </td> <td> <div> 10 días<br> </div> </td> <td> <div> Recibida una solicitud de permiso, la CNE debe revisar que la misma cumple con lo previsto en las Disposiciones de Permisos. En su caso, la CNE debe realizar la prevención correspondiente cuando la solicitud no cuente con la información o requisitos correspondientes, a través de la OPE.</div> <div> La persona solicitante o la CFE debe dar atención en tiempo y forma a la prevención que, en su caso, se le haya realizado, a través de la OPE; de no hacerlo, se debe desechar la solicitud.</div> </td> </tr> <tr> <td> <div> 3<br> </div> </td> <td> <div> Evaluación de criterios de planeación vinculante por parte de la CNE.</div> </td> <td> <div> 7 días<br> </div> </td> <td> <div> La CNE debe llevar a cabo la evaluación conforme a lo previsto en las Disposiciones de la Planeación Vinculante.</div> </td> </tr> <tr> <td> <div> 4<br> </div> </td> <td> <div> Resolución de las solicitudes de permisos por parte de la CNE.</div> </td> <td> <div> 5 días<br> </div> </td> <td> <div> La CNE debe resolver lo conducente respecto de las solicitudes de permisos correspondientes.</div> </td> </tr> <tr> <td> <div> 5<br> </div> </td> <td> <div> Notificación de la resolución de las solicitudes de permisos.</div> </td> <td> <div> 1 día<br> </div> </td> <td> <div> La CNE debe notificar la resolución de la solicitud del permiso de que se trate, a través de la OPE.</div> </td> </tr> <tr> <td> <div> 6<br> </div> </td> <td> <div> Desistimiento de solicitudes de permisos.</div> </td> <td> <div> 4 días<br> </div> </td> <td> <div> Tratándose de solicitudes con trámite previo, la persona solicitante a la que se le haya notificado el otorgamiento del permiso correspondiente debe desistirse de la solicitud de permiso previa ante la CNE.</div> </td> </tr> <tr> <td> <div> 7<br> </div> </td> <td> <div> Ejecución y seguimiento del programa de obras.</div> </td> <td> <div> A partir de la notificación<br> del título de permiso o<br> instrumento<br> correspondiente<br> </div> </td> <td> <div> La persona solicitante o la CFE debe cumplir con los plazos y términos establecidos en el título de permiso otorgado.</div> </td> </tr> <tr> <td> <div> 8<br> </div> </td> <td> <div> Presentación y validación de garantías financieras.</div> </td> <td> <div> Previo a la firma del<br> contrato de interconexión<br> </div> </td> <td> <div> La persona solicitante o la CFE debe presentar las garantías financieras correspondientes para poder llevar a cabo la celebración del contrato para la interconexión, conexión o ambas a la Red Nacional de Transmisión o a las Redes Generales de Distribución, según corresponda.</div> <div> Presentadas las garantías financieras, el CENACE debe validarlas y, en su caso, instruir la firma del contrato de interconexión o conexión correspondiente.</div> </td> </tr> <tr> <td> <div> 9<br> </div> </td> <td> <div> Suscripción del contrato de interconexión.</div> </td> <td> <div> 10 días<br> </div> </td> <td> <div> La persona solicitante o la CFE debe presentar la documentación e información que requiere el CENACE para suscribir el contrato o instrumento correspondiente.</div> <div> Una vez presentada la garantía financiera correspondiente y cumplidos los requisitos aplicables, las entidades responsables y la persona solicitante, a través de la VUPE, deben realizar las gestiones necesarias para la suscripción del contrato para la interconexión, conexión o ambas, en términos de la normatividad aplicable.</div> </td> </tr> <tr> <td> <div> 10<br> </div> </td> <td> <div> Interconexión o conexión física al SEN.</div> </td> <td> <div> 10 días<br> </div> </td> <td> <div> La CFE debe realizar las acciones necesarias para realizar la interconexión o conexión del proyecto de que se trate al SEN.</div> </td> </tr> <tr> <td> <div> 11<br> </div> </td> <td> <div> Entrada en Operación Comercial.</div> </td> <td> <div> Según título de permiso<br> </div> </td> <td> <div> La persona solicitante y la CFE deben realizar las acciones necesarias para lograr la Entrada en Operación Comercial del proyecto.</div> <div> La SENER, a través del Consejo de Planeación Energética, así como la CNE y el CENACE, deben dar seguimiento al desarrollo de los proyectos hasta su Entrada en Operación Comercial.</div> </td> </tr> </tbody></table>\n<div> &quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 17.4"},{"id":"31199c7d-36ae-56e8-919e-de6d6724dbb2","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":21,"identificador":"PRIMERO · Texto citado del numeral 17.4.1","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;17.4.1. Para efectos del procedimiento de otorgamiento de permisos en términos de la Convocatoria de Proyectos Estratégicos, los plazos y etapas para su atención corresponden a los señalados en la misma.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 17.4.1"},{"id":"aca19cd1-ba19-5ddf-a63d-798856366b86","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":22,"identificador":"PRIMERO · Texto citado del numeral 18","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;18. Referencias de Capacidad Requerida para la Convocatoria de Proyectos Estratégicos de Sistemas de Almacenamiento de Energía Eléctrica y Generación de Energía Eléctrica</div>\n<div> La referencia de Capacidad Requerida para la Convocatoria de Proyectos Estratégicos establece las cantidades para identificar las necesidades generales de generación y almacenamiento de energía eléctrica, dando prioridad a los proyectos cuya Entrada en Operación Comercial esté prevista antes de 2030, de acuerdo con lo siguiente:</div>\n<div> 18.1...</div>\n<div> Para la generación de energía eléctrica, la referencia de Capacidad Requerida para la Convocatoria de Proyectos Estratégicos considera la planeación vinculante y las condiciones operativas del SEN.&quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 18"},{"id":"005bb5c7-c2e7-5777-8201-20803f43db45","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":23,"identificador":"PRIMERO · Texto citado del numeral 18.2","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> &quot;18.2 ...</div>\n<div> ...</div>\n<table> <tbody><tr> <td> <div> Gerencia de Control Regional<br> </div> </td> <td> <div> Capacidad Requerida para la Convocatoria de<br> Proyectos Estratégicos (MW)<br> </div> </td> <td> <div> Horas de almacenamiento<br> </div> </td> </tr> <tr> <td> <div> Baja California<br> </div> </td> <td> <div> 140<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Baja California Sur<br> </div> </td> <td> <div> 50<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Norte<br> </div> </td> <td> <div> 245<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Noroeste<br> </div> </td> <td> <div> 160<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Oriental<br> </div> </td> <td> <div> 180<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Occidental<br> </div> </td> <td> <div> 20<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Peninsular<br> </div> </td> <td> <div> 140<br> </div> </td> <td> <div> 3 horas<br> </div> </td> </tr> <tr> <td> <div> Total<br> </div> </td> <td> <div> 935<br> </div> </td> <td> <div>  </div> </td> </tr> </tbody></table>\n<div> &quot;</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo PRIMERO del acuerdo modificatorio","seccion_nombre":"Texto citado del numeral 18.2"},{"id":"f01bebbb-7cbe-5047-902c-72e90f73580a","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":24,"identificador":"Resolutivo SEGUNDO","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> SEGUNDO. Los plazos y referencias contenidos en la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante, deben entenderse conforme a lo previsto en la modificación a la que se refiere el numeral anterior.</div>","tipo_articulo":"ordinario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","seccion_nombre":null},{"id":"fdd3f92f-2bc3-5c5b-842e-f4eea34e1a62","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":25,"identificador":"Transitorio PRIMERO · acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> TRANSITORIOS<br> </div>\n<div> PRIMERO. El presente Acuerdo entrará en vigor el mismo día de su publicación en el Diario Oficial  de la Federación.</div>","tipo_articulo":"transitorio","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Transitorios del acuerdo modificatorio","seccion_nombre":null},{"id":"6d8df6c7-425d-5d26-8ea7-17dfbe59de76","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":26,"identificador":"Transitorio SEGUNDO · acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> SEGUNDO. Para el caso de aquellas personas solicitantes que hayan presentado registros de manifestación de interés y solicitudes de estudios de interconexión y conexión previo a la fecha de publicación de este Acuerdo, en un plazo no mayor a 5 días hábiles, deben manifestar su interés en continuar con el procedimiento de la Convocatoria de Proyectos Estratégicos conforme al procedimiento establecido previo a la entrada en vigor del presente Acuerdo.</div>\n<div> En caso de que las personas solicitantes no manifiesten el interés al que se refiere el párrafo anterior, el procedimiento continuará conforme a lo establecido en el presente Acuerdo.</div>","tipo_articulo":"transitorio","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Transitorios del acuerdo modificatorio","seccion_nombre":null},{"id":"886cc40d-45e2-5e2e-bae0-f136b718d008","ley_id":"29886758-c194-5db4-86eb-8c96347f7aba","orden":27,"identificador":"Firma del acuerdo","contenido":"<!-- ### Transcripción de la publicación oficial -->\n\n<div> Ciudad de México, a 7 de julio de 2026.- La Secretaria de Energía, Luz Elena González Escobar.- Rúbrica.</div>","tipo_articulo":"complementario","titulo_nombre":"Proyectos estratégicos de generación y almacenamiento · publicación del 10-07-2026","capitulo_nombre":"Documentos complementarios","seccion_nombre":null}],"temas":[{"nivel":"titulo","nombre":"Información editorial de la versión","orden":0},{"nivel":"capitulo","nombre":"Resolutivo PRIMERO del acuerdo modificatorio","orden":1},{"nivel":"seccion","nombre":"Texto citado del numeral 1","orden":2},{"nivel":"seccion","nombre":"Texto citado del numeral 2","orden":3},{"nivel":"seccion","nombre":"Texto citado del numeral 3.1","orden":4},{"nivel":"seccion","nombre":"Texto citado del numeral 5.1","orden":5},{"nivel":"seccion","nombre":"Texto citado del numeral 6.2","orden":6},{"nivel":"seccion","nombre":"Texto citado del numeral 8.1","orden":7},{"nivel":"seccion","nombre":"Texto citado del numeral 8.3","orden":8},{"nivel":"seccion","nombre":"Texto citado del numeral 9.1","orden":9},{"nivel":"seccion","nombre":"Texto citado del numeral 10.1","orden":10},{"nivel":"seccion","nombre":"Texto citado del numeral 10.2","orden":11},{"nivel":"seccion","nombre":"Texto citado del numeral 10.3","orden":12},{"nivel":"seccion","nombre":"Texto citado del numeral 11.1","orden":13},{"nivel":"seccion","nombre":"Texto citado del numeral 12.1","orden":14},{"nivel":"seccion","nombre":"Texto citado del numeral 14","orden":15},{"nivel":"seccion","nombre":"Texto citado del numeral 17.1","orden":16},{"nivel":"seccion","nombre":"Texto citado del numeral 17.2","orden":17},{"nivel":"seccion","nombre":"Texto citado del numeral 17.3","orden":18},{"nivel":"seccion","nombre":"Texto citado del numeral 17.4","orden":19},{"nivel":"seccion","nombre":"Texto citado del numeral 17.4.1","orden":20},{"nivel":"seccion","nombre":"Texto citado del numeral 18","orden":21},{"nivel":"seccion","nombre":"Texto citado del numeral 18.2","orden":22},{"nivel":"capitulo","nombre":"Resolutivo SEGUNDO del acuerdo modificatorio","orden":23},{"nivel":"capitulo","nombre":"Transitorios del acuerdo modificatorio","orden":24}],"fuente":{"name":"CONV-ESTRATEGICOS-M2","code":"5793261","radar":"RAD-045","familia":"Proyectos estratégicos de generación y almacenamiento","modificacion":2,"url":"https://sidof.segob.gob.mx/notas/docFuente/5793261","sha256":"98316b040369fce7f60f4071726ff4712d6a9d045acf0f8609db5d3be343f70d","fecha":"10-07-2026","titulo":"Acuerdo por el que se emite la segunda modificación a la Convocatoria para la Atención de Proyectos Estratégicos de Generación y Almacenamiento de Energía Eléctrica, alineados a la planeación vinculante.","codDiario":328425,"pagina":11,"tables":3,"images":[]}}$payload$::jsonb; lid uuid;
BEGIN
 lid := (p->'ley'->>'id')::uuid;
 LOCK TABLE public.leyes,public.articulos,public.temas IN SHARE ROW EXCLUSIVE MODE;
 IF EXISTS(SELECT 1 FROM public.leyes WHERE id=lid OR lower(siglas)=lower(p->'ley'->>'siglas') OR lower(titulo)=lower(p->'ley'->>'titulo') OR url_original=p->'ley'->>'url_original') THEN RAISE EXCEPTION 'El instrumento ya existe: revisar, no reemplazar'; END IF;
 INSERT INTO public.leyes(id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) SELECT id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo FROM jsonb_populate_record(null::public.leyes,p->'ley');
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden) SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'articulos');
 INSERT INTO public.temas(ley_id,nivel,nombre,orden) SELECT lid,t->>'nivel',t->>'nombre',(t->>'orden')::int FROM jsonb_array_elements(p->'temas')t;
 IF (SELECT count(*)FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'articulos') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'articulos')b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'Fallo de cotejo exacto de artículos'; END IF;
 IF (SELECT count(*)FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'temas') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'temas')b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE ley_id=lid AND (to_jsonb(t)-'id'-'ley_id'-'created_at')=b)) THEN RAISE EXCEPTION 'Fallo de cotejo de estructura'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.leyes l WHERE id=lid AND to_jsonb(l)-'created_at'=p->'ley') THEN RAISE EXCEPTION 'Metadatos diferentes'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'')IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o índice FTS vacío'; END IF;
END $ingest$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*)FROM public.articulos a WHERE a.ley_id=l.id)fragmentos,(SELECT count(*)FROM public.temas t WHERE t.ley_id=l.id)temas FROM public.leyes l WHERE l.id='29886758-c194-5db4-86eb-8c96347f7aba';
